import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"开发者手册","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 架构与开发流程","slug":"_1-架构与开发流程","link":"#_1-架构与开发流程","children":[]},{"level":2,"title":"2. 插件 SDK 接口参考","slug":"_2-插件-sdk-接口参考","link":"#_2-插件-sdk-接口参考","children":[]}],"relativePath":"zh-CN/dev-guide/index.md","filePath":"zh-CN/dev-guide/index.md","lastUpdated":1791123169000}`),a={name:`zh-CN/dev-guide/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="开发者手册" tabindex="-1">开发者手册 <a class="header-anchor" href="#开发者手册" aria-label="Permalink to “开发者手册”">​</a></h1><p>欢迎查阅 Lertaro 开发者参考手册。Lertaro 采用解耦架构与开放的插件生态，提供官方 SDK 程序集 <code>Lertaro.PluginSdk</code>。开发者可以通过引用该 SDK，为 Lertaro 贡献自定义搜索源、扩展右键上下文动作、适配第三方文件管理器与原生对话框，或者定制主题与文件预览组件。</p><h2 id="_1-架构与开发流程" tabindex="-1">1. 架构与开发流程 <a class="header-anchor" href="#_1-架构与开发流程" aria-label="Permalink to “1. 架构与开发流程”">​</a></h2><ul><li><strong><a href="./architecture.html">系统架构设计</a></strong> —— 详解 SYSTEM 级 Windows 索引服务、用户态 WPF 交互进程与独立键盘钩子进程的三进程隔离模型与命名管道 IPC 通信机制。</li><li><strong><a href="./getting-started.html">快速上手指南</a></strong> —— 从零创建插件类库工程、引用 SDK、实现 <code>IPlugin</code> 入口以及本地调试的最佳实践。</li><li><strong><a href="./packaging.html">打包与分发</a></strong> —— 插件程序集目录结构规范、第三方托管/原生依赖库打包、多语言 JSON 资源内嵌与 PostBuild 自动部署。</li><li><strong><a href="./examples.html">官方插件范例</a></strong> —— 剖析随包开源的 <code>CoreExtensions</code>、<code>PinyinAlias</code>、<code>FlowLauncherBridge</code> 与 <code>FileUnlocker</code> 等真实插件的实现代码。</li></ul><h2 id="_2-插件-sdk-接口参考" tabindex="-1">2. 插件 SDK 接口参考 <a class="header-anchor" href="#_2-插件-sdk-接口参考" aria-label="Permalink to “2. 插件 SDK 接口参考”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK 模块分类</th><th style="text-align:left;">核心接口与服务</th><th style="text-align:left;">关键功能说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">核心检索与动作</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">贡献静态索引源、高频即时计算答案、非 ASCII 别名转写引擎、尾部 Token 后缀处理器以及静态/动态上下文动作菜单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">系统与对话框适配</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">探测前台管理器活动目录、挂载原生文件对话框、内嵌搜索条并双向同步选中状态、贡献鼠标快速导航级联菜单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">界面与预览扩展</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>ICalendarTextProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">扩展侧边栏筛选分类、表格视图自定义列、快速面板动态工作区标签、搜索窗口时钟行的日期文字、QuickLook 自定义渲染器与缩略图提取、WPF 资源字典主题包与多语言 i18n。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">共享抽象契约</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">检索结果只读数据契约、纳秒级文件时间戳与大小元数据、宿主窗口安全控制句柄与基于模式驱动的原生配置表单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">宿主开放服务</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>MemoryMaintenanceService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">宿主暴露的高性能基础设施：fzf 模糊匹配与高亮掩码、多语言解析、带缓存图标提取、收藏管理与历史读取、后台目录索引代理、延迟内存维护、用户数据目录隔离及 Shell 原生文件操作。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/notifications.html">通知</a></strong></td><td style="text-align:left;"><code>PluginNotificationService</code><br><code>NotificationRequest</code><br><code>INotificationHandle</code><br><code>NotificationLevel</code><br><code>NotificationPosition</code><br><code>NotificationResult</code><br><code>NotificationFailure</code></td><td style="text-align:left;">通过宿主自己的窗口在后台获得用户注意：右下角的卡片堆或底部居中的一行提示、由宿主裁剪的时长、按 <code>Id</code> 替换、按插件计数的上限，以及一定会完成的结束任务。</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>本手册各页的接口签名、成员名称、默认值与参数顺序均直接读取自 <code>Lertaro.PluginSdk</code> 源码。若某页同时描述了<strong>宿主</strong>对插件调用的反应，该句只是对当前行为的说明，并非插件可以依赖的契约。</p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};